WITH filtered AS (SELECT *, CASE WHEN country IN ('DE', 'UK') THEN 'Core' ELSE 'Other' END country_group, CASE WHEN country IN ('SG', 'US') THEN 'Group A' ELSE 'Other' END country_group_2, COALESCE(browser, 'UNKNOWN') browser_clean FROM sessions WHERE started_at > TIMESTAMP '2023-08-21 02:00:00' AND country = 'UK') SELECT device, browser, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, MIN(started_at) AS first_started_at, SORT_ARRAY(COLLECT_SET(country)) AS country_list, SORT_ARRAY(COLLECT_SET(device)) AS device_list, COUNT(CASE WHEN country = 'JP' THEN 1 END) AS jp_count FROM filtered GROUP BY GROUPING SETS ((device, browser), (device), ()) HAVING (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 > 0 ORDER BY device ASC NULLS LAST;
